package com.project.common.config;
import java.util.*;import javax.servlet.http.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.context.annotation.Configuration;import org.springframework.web.method.HandlerMethod;import org.springframework.web.servlet.*;import org.springframework.web.servlet.config.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.apache.shiro.SecurityUtils;import org.apache.shiro.subject.Subject;import org.apache.shiro.authz.annotation.RequiresPermissions;
@Configuration public class PermissionGuard implements WebMvcConfigurer {
 @Autowired private JdbcTemplate db;
 @Override public void addInterceptors(InterceptorRegistry registry){registry.addInterceptor(new HandlerInterceptor(){@Override public boolean preHandle(HttpServletRequest request,HttpServletResponse response,Object handler)throws Exception{return authorize(request,response,handler);}});}
 private boolean authorize(HttpServletRequest request,HttpServletResponse response,Object handler)throws Exception{
 if(!(handler instanceof HandlerMethod))return true;Subject subject=SecurityUtils.getSubject();if(subject.getPrincipal()==null)return true;if(com.project.common.utils.ShiroUtils.getUser().isSuperAdmin())return true;
 HandlerMethod h=(HandlerMethod)handler;String type=h.getBeanType().getSimpleName(),method=h.getMethod().getName(),permission=null;
 if(type.equals("WalletController")){if(Arrays.asList("page","data","person","history","detail").contains(method)){permission="campus:wallet:view";String target=request.getParameter("user");if(method.equals("detail"))target=request.getRequestURI().substring(request.getRequestURI().lastIndexOf('/')+1);if(target!=null&&!target.equals(String.valueOf(com.project.common.utils.ShiroUtils.getUserId())))permission="campus:wallet:list";}else if(method.equals("search"))permission="campus:wallet:list";else if(method.equals("trade")){String kind=request.getParameter("kind");permission="RECHARGE".equals(kind)?"campus:wallet:recharge":"REFUND".equals(kind)?"campus:wallet:debit":"campus:consumption:pay";}else if(method.equals("debit"))permission="campus:wallet:debit";else if(method.equals("status"))permission="campus:wallet:status";else if(method.equals("verification"))permission="campus:wallet:verify";else if(method.equals("reconcile"))permission="campus:wallet:report";else permission="campus:wallet:recharge";
 }else if(type.equals("MerchantController")){if(method.startsWith("consumption")){permission=method.equals("consumptionPay")?"campus:consumption:pay":method.equals("consumptionData")?"campus:consumption:list":"campus:consumption:view";}else if(method.equals("save"))permission="campus:merchant:save";else if(method.equals("status"))permission="campus:merchant:status";else if(method.equals("category"))permission="campus:merchant:category";else if(method.equals("upload"))permission="campus:merchant:upload";else if(method.equals("search"))permission="campus:merchant:list";else permission="campus:merchant:view";
 }else if(type.equals("RoleController")||type.equals("MenuController")){permission="GET".equals(request.getMethod())?"system:permission:view":"system:permission:grant";
 }else if(h.hasMethodAnnotation(RequiresPermissions.class))return true;
 else if(type.equals("UserController")){if(Arrays.asList("updateSelf","updateSecret","updatePwd","checkPassword","checkLoginNameUnique","checkPhoneUnique","checkEmailUnique").contains(method))return true;permission=method.startsWith("resetPwd")?"system:user:resetPwd":"GET".equals(request.getMethod())?"system:user:view":"system:user:edit";}
 else if(request.getRequestURI().startsWith("/system/")&&!type.equals("IndexController")){String path=request.getRequestURI();List<Map<String,Object>> menus=db.queryForList("select url,perms from sys_menu where menu_type='C' and url<>'#' and perms<>'' order by length(url) desc");for(Map<String,Object> m:menus){String url=String.valueOf(m.get("url"));if(path.equals(url)||path.startsWith(url+"/")){permission=String.valueOf(m.get("perms"));break;}}}
 if(permission==null||subject.isPermitted(permission))return true;response.setStatus(403);response.setCharacterEncoding("UTF-8");response.setContentType("application/json;charset=UTF-8");response.getWriter().write("{\"error\":\"没有执行此功能的权限，请联系管理员授权\"}");return false;
 }
}
